export class RollingMedian {
	/** @param {number} windowSize */
	constructor(windowSize) {
		this.#windowSize = this.#checkWindowSize(windowSize);
		/** @type {number[]} */
		this.#values = [];
	}

	/** @param {number} n @returns {number} */
	#checkWindowSize(n) {
		if (!Number.isInteger(n) || n < 1) {
			throw new RangeError(`windowSize must be an integer of 1 or more, got ${n}`);
		}
		return n;
	}

	/** @param {number} x @returns {number} */
	add(x) {
		if (typeof x !== "number" || !Number.isFinite(x)) {
			throw new TypeError(`x must be a finite number, got ${x}`);
		}
		this.#values.push(x);
		while (this.#values.length > this.#windowSize) {
			this.#values.shift();
		}
		return this.median();
	}

	/** @returns {number | null} */
	median() {
		const n = this.#values.length;
		if (n === 0) return null;
		const sorted = [...this.#values].sort((a, b) => a - b);
		return sorted[Math.floor((n - 1) / 2)];
	}

	/** @returns {number} */
	get size() {
		return this.#values.length;
	}

	/** @returns {number[]} */
	values() {
		return [...this.#values];
	}

	reset() {
		this.#values = [];
	}

	/** @param {number} n @returns {number | null} */
	resize(n) {
		this.#windowSize = this.#checkWindowSize(n);
		while (this.#values.length > this.#windowSize) {
			this.#values.shift();
		}
		return this.median();
	}
}

