cat > /tmp/sanity.mjs <<'EOF'
import assert from "node:assert/strict";
import { RollingMedian } from "./src/rolling-median.js";

// R1
for (const bad of [0, -1, 1.5, NaN, "3", null, undefined, true, Infinity]) {
  assert.throws(() => new RollingMedian(bad), RangeError, `ctor ${bad}`);
}
assert.ok(new RollingMedian(1) instanceof RollingMedian);

// R2
const m = new RollingMedian(3);
assert.equal(m.median(), null);
assert.equal(m.add(4), 4);
assert.equal(m.add(2), 2);
for (const bad of [NaN, Infinity, -Infinity, "5", 5n, null, undefined, {}, []]) {
  assert.throws(() => m.add(bad), TypeError, `add ${String(bad)}`);
}
assert.deepEqual(m.values(), [4, 2]); // unchanged after invalid adds
assert.equal(m.size, 2);

// R3 even window -> lower middle
assert.equal(m.add(1), 1);   // [4,2,1]
assert.equal(m.add(3), 2);   // [4,2,1,3] sorted [1,2,3,4] -> 2 (lower middle)
assert.equal(m.add(0), 1);   // drops 4 -> [2,1,3,0] wait window is 3!

// Redo: windowSize 3: after 5 adds, window = [1,3,0]
assert.deepEqual(m.values(), [1, 3, 0]);
assert.equal(m.median(), 1);

// R4
const v = m.values();
v.push(99);
assert.equal(m.size, 3);

// R5
assert.equal(m.reset(), undefined);
assert.equal(m.size, 0);
assert.equal(m.median(), null);

// R6
assert.equal(m.resize(2), null);
assert.equal(m.add(7), 7);
assert.equal(m.add(5), 5);
assert.equal(m.size, 2);
assert.equal(m.resize(1), 7); // drops oldest 5 -> [7]
assert.deepEqual(m.values(), [7]);
assert.equal(m.add(9), 7);    // window [9]? no: push 9 -> [7,9] -> drop 7 -> [9] median 9
assert.deepEqual(m.values(), [9]);
assert.throws(() => m.resize(0), RangeError);
assert.throws(() => m.resize(2.5), RangeError);

// negatives & zeros ordering
const n = new RollingMedian(4);
n.add(-2); n.add(0); n.add(-5); n.add(3);
assert.equal(n.median(), -2); // sorted [-5,-2,0,3] lower middle -2

console.log("all sanity checks passed");
EOF
